// ─── File: EnvelopeEstimatorDemo.java ───
// Back-of-envelope capacity estimate: QPS, storage, bandwidth, cache,
// anchored by the latency numbers every engineer should know.
import java.util.logging.*;

public class EnvelopeEstimatorDemo {
    private static final Logger log = Logger.getLogger("EST");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SystemAssumptions a = new SystemAssumptions(
                10_000_000L, // daily active users
                3,           // reads per user per day (history checks)
                5,           // writes per user per day (transactions)
                1024,        // bytes per record
                7,           // retention years
                4);          // peak multiplier
        EnvelopeEstimator est = new EnvelopeEstimator(100_000, 2.0, 3, 0.20, 2);

        long avgQps = est.averageQps(a);
        long peakQps = est.peakQps(a);
        long readQps = est.readQps(a);
        long writeQps = est.writeQps(a);
        double tbPerYear = est.storagePerYearTB(a);
        double tbRetained = est.storageOverRetentionTB(a);
        double egressMbps = est.egressMbps(peakQps);
        double cacheGb = est.cacheSizeGB(a);

        log.info(() -> "Average QPS = " + avgQps + ", Peak QPS = " + peakQps);
        log.info(() -> "Read QPS = " + readQps + " (replicas/cache), Write QPS = " + writeQps + " (primary)");
        log.info(() -> "Storage/year = " + round(tbPerYear) + " TB, over 7y with index+replication = "
                + round(tbRetained) + " TB → needs sharding");
        log.info(() -> "Peak egress = " + round(egressMbps) + " Mbps");
        log.info(() -> "Cache (hot 20%) = " + round(cacheGb) + " GB → fits one Redis cluster");

        LatencyReference.printAnchors();
    }
    static double round(double v) { return Math.round(v * 10) / 10.0; }
}

// ─── model/SystemAssumptions.java ───
class SystemAssumptions {
    final long dau; final int reads, writes, recordBytes, retentionYears, peakMultiplier;
    SystemAssumptions(long dau, int reads, int writes, int recordBytes, int retentionYears, int peakMultiplier) {
            this.dau = dau;
            this.reads = reads
            this.writes = writes;
            this.recordBytes = recordBytes;
            this.retentionYears = retentionYears
            this.peakMultiplier = peakMultiplier;
    }
}

// ─── calc/EnvelopeEstimator.java ───
class EnvelopeEstimator {
    private final int secondsPerDay; private final double indexFactor;
    private final int replication; private final double hotFraction; private final int responseKb;
    EnvelopeEstimator(int secondsPerDay, double indexFactor, int replication, double hotFraction, int responseKb) {
            this.secondsPerDay = secondsPerDay;
            this.indexFactor = indexFactor;
            this.replication = replication;
            this.hotFraction = hotFraction
            this.responseKb = responseKb;
    }
    long averageQps(SystemAssumptions a) {
        long dailyRequests = a.dau * (a.reads + a.writes);
        return dailyRequests / secondsPerDay;
    }
    long peakQps(SystemAssumptions a) { return averageQps(a) * a.peakMultiplier; }
    long readQps(SystemAssumptions a) {
        return (long) (peakQps(a) * ((double) a.reads / (a.reads + a.writes)));
    }
    long writeQps(SystemAssumptions a) { return peakQps(a) - readQps(a); }
    double storagePerYearTB(SystemAssumptions a) {
        long bytesPerDay = a.dau * a.writes * a.recordBytes;   // only writes persist records
        double rawPerYearTB = bytesPerDay * 365L / 1e12;
        return rawPerYearTB * indexFactor * replication;        // indexes + replicas
    }
    double storageOverRetentionTB(SystemAssumptions a) { return storagePerYearTB(a) * a.retentionYears; }
    double egressMbps(long peakQps) {
        double bytesPerSec = peakQps * responseKb * 1024.0;
        return bytesPerSec * 8 / 1e6;                           // bytes→bits→Mbps
    }
    double cacheSizeGB(SystemAssumptions a) {
        double hotItems = a.dau * hotFraction;
        return hotItems * a.recordBytes / 1e9;
    }
}

