class LatencyReference {
    private static final Logger log = Logger.getLogger("EST");
    static void printAnchors() {
        log.info("──── Latency numbers every engineer should know ────");
        log.info("L1 cache ~1ns | RAM ref ~100ns | read 1MB RAM ~10us");
        log.info("SSD random read ~100us (1000x slower than RAM)");
        log.info("Same-DC round trip ~500us | read 1MB SSD ~1ms");
        log.info("Disk seek ~10ms | CA↔Netherlands round trip ~150ms");
    }
}

